const series = (context.panel.data && context.panel.data.series) || [];
const xSeries = series.find((s) => s.refId === 'A');
const ySeries = series.find((s) => s.refId === 'B');
const mmdSeries = series.find((s) => s.refId === 'C');

const toRows = (s) => {
  if (!s || !s.fields || s.fields.length === 0) return [];
  const valueField = s.fields.find((f) => f.type === 'number') || s.fields[s.fields.length - 1];
  const labels = (valueField && valueField.labels) || {};
  const values = (valueField && valueField.values) ? valueField.values.toArray() : [];
  if (values.length === 0) return [];
  const last = values[values.length - 1];
  return [{ source: labels.source || 'live', request_id: labels.request_id || 'unknown', value: Number(last) }];
};

const xRows = (xSeries ? xSeries.fields : []).flatMap((f) => {
  if (f.type !== 'number') return [];
  const labels = f.labels || {};
  const vals = f.values ? f.values.toArray() : [];
  if (vals.length === 0) return [];
  return [{ source: labels.source || 'live', request_id: labels.request_id || 'unknown', x: Number(vals[vals.length - 1]) }];
});

const yRows = (ySeries ? ySeries.fields : []).flatMap((f) => {
  if (f.type !== 'number') return [];
  const labels = f.labels || {};
  const vals = f.values ? f.values.toArray() : [];
  if (vals.length === 0) return [];
  return [{ source: labels.source || 'live', request_id: labels.request_id || 'unknown', y: Number(vals[vals.length - 1]) }];
});

const yMap = new Map(yRows.map((r) => [`${r.source}/${r.request_id}`, r.y]));
const points = xRows
  .map((r) => ({
    source: r.source,
    request_id: r.request_id,
    x: r.x,
    y: yMap.get(`${r.source}/${r.request_id}`),
  }))
  .filter((r) => Number.isFinite(r.x) && Number.isFinite(r.y));

const refPoints = points.filter((p) => p.source === 'reference').map((p) => [p.x, p.y]);
const livePoints = points.filter((p) => p.source === 'live').map((p) => [p.x, p.y]);

let mmd = 0;
if (mmdSeries && mmdSeries.fields) {
  const mmdField = mmdSeries.fields.find((f) => f.type === 'number');
  const vals = mmdField && mmdField.values ? mmdField.values.toArray() : [];
  if (vals.length > 0) mmd = Number(vals[vals.length - 1]);
}

const liveColor = mmd > 0.25 ? '#e03131' : '#1c7ed6';

return {
  backgroundColor: 'transparent',
  animationDuration: 300,
  title: {
    text: `Reference vs Live Embeddings (MMD=${mmd.toFixed(3)})`,
    left: 'center',
    textStyle: { fontSize: 13 }
  },
  tooltip: { trigger: 'item' },
  xAxis: { type: 'value', name: 'embedding_x' },
  yAxis: { type: 'value', name: 'embedding_y' },
  series: [
    {
      name: 'Reference',
      type: 'scatter',
      data: refPoints,
      symbolSize: 8,
      itemStyle: { color: '#868e96', opacity: 0.45 },
      emphasis: { disabled: true },
      animation: false
    },
    {
      name: 'Live',
      type: 'scatter',
      data: livePoints,
      symbolSize: 10,
      itemStyle: { color: liveColor, opacity: 0.9 },
      animationDurationUpdate: 350,
      universalTransition: true
    }
  ]
};
